/* ON Mission 16.55.0 — Unified Asset Studio create/edit convergence surface.
 * Single Super Admin resource operating surface over canonical authorities.
 * The UI orchestrates; domain services own truth, lifecycle, authorization and mutation.
 */
import {$,api,esc,state,ensureStepUp} from './admin-runtime.js?v=16.57.0';
import {openResourceExplorer,runResourceAction,restoreResource} from './resource-explorer.js?v=16.57.0';
import {renderDataStudio} from './data-studio.js?v=16.57.0';
import {buildAssetContract,ASSET_FAMILIES} from './asset-contract-engine.js?v=16.57.0';

const LABELS={sector_lifecycle:'Sector Lifecycle',translation_bundle:'Translation Bundle',country_blueprint:'Country Blueprint',product_country:'Product Country',sector:'Sector',language:'Language',currency:'Currency',region:'Region',classification:'Classification',policy:'Policy',residency:'Residency Rule',retention:'Retention Rule',consent:'Consent',role:'Role',capability:'Capability',responsibility:'Responsibility Rule',storage:'Storage',provider:'Provider',component:'Component',page:'Page',feature:'Feature',configuration:'Configuration',guidance:'Guidance',plan:'Billing Plan',mission_plan:'Mission Plan',eligibility:'Eligibility Rule',pricing:'Pricing'};
const OBJECT_FIELDS=new Set(['payload','configuration','rule','states','transitions','prerequisites','evidenceRequirements','recoveryPaths','translations']);
const FIELD_HINTS={countryCode:'ISO country code',defaultLanguageCode:'Supported default language',code:'Stable canonical code',domainCode:'Owning domain',roleCode:'Existing role code',providerCode:'Registered provider code',regionCode:'Canonical region code',purposeCode:'Consent purpose identifier',priceMinor:'Minor currency unit',billingInterval:'month / year / one_time',days:'Retention period in days'};
// Canonical navigation taxonomy; family labels are classification only, not separate authorities.
const ASSET_FAMILY_LABELS=['Data assets','Logical assets','Visible assets','Operational assets','Service & integration assets','Governance & release assets'];
let definitions=[];let recent=[];let visibleResources=[];let currentSearchId=0;let workspaceNavigator=()=>{};
// Keep inventory completeness visible across search, filtering, and refresh renders.
let inventoryHealth={state:'UNKNOWN',unavailableAuthorities:[]};
const inventoryFilters={type:'all',status:'all'};
const text=v=>esc(v==null?'':String(v));
const label=t=>LABELS[t]||String(t||'Resource').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase());
const canonicalType=t=>String(t||'').trim().toLowerCase().replaceAll('-','_').replaceAll(' ','_');
const canonicalTypeSafe=t=>String(t||'').trim().toLowerCase().replaceAll('-','_').replaceAll(' ','_');
const resourceId=(type,x)=>String(x?.id??x?.code??x?.role_code??'');
const resourceName=(type,x)=>String(x?.name??x?.label??x?.title??x?.display_name??x?.code??`${label(type)} ${resourceId(type,x)}`);
const resourceStatus=x=>String(x?.status??(x?.active===0?'inactive':x?.active===1||x?.active===true?'active':'unknown'));
const updatedAt=x=>x?.updated_at||x?.updatedAt||x?.created_at||x?.createdAt||'';
const riskClass=r=>r==='high'?'warn':r==='medium'?'neutral':'ok';
function resourceFromRecent(type,x){const id=resourceId(type,x);if(!id)return null;return {type,id,name:resourceName(type,x),status:resourceStatus(x),updatedAt:updatedAt(x),subtitle:`${label(type)} · ${id}`};}
function flattenRecent(data){return Object.entries(data||{}).flatMap(([type,list])=>(Array.isArray(list)?list:[]).map(x=>resourceFromRecent(type,x)).filter(Boolean)).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,24)}
function fieldInput(field,d){const schema=d?.fieldSchemas?.[field]||{};const lab=field.replace(/([A-Z])/g,' $1').replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());const hint=FIELD_HINTS[field]||(schema.relation?`Canonical ${schema.relation} asset identity`:'');const req=schema.required||['name','code','title','purposeCode'].includes(field);const common=`class="input resource-add-field" data-field="${text(field)}" ${req?'required':''}`;if(schema.type==='json'||OBJECT_FIELDS.has(field))return `<label class="field full"><span>${text(lab)}</span><textarea ${common} rows="7" placeholder="${text(field==='states'?'[{"code":"created","terminal":false}]':field==='transitions'?'[{"from":"created","to":"assigned","action":"assign"}]':'{}')}"></textarea><small class="mini">Structured JSON validated by the owning authority${hint?` · ${text(hint)}`:''}</small></label>`;if(schema.type==='boolean')return `<label class="field"><span><input type="checkbox" data-field="${text(field)}" data-value-type="boolean" ${schema.default?'checked':''}> ${text(lab)}</span><small class="mini">Explicit true/false setting</small></label>`;if(schema.type==='enum')return `<label class="field"><span>${text(lab)}</span><select ${common}>${(schema.options||[]).map(o=>`<option value="${text(o)}" ${schema.default===o?'selected':''}>${text(o)}</option>`).join('')}</select></label>`;const type=schema.type==='integer'?'number':schema.type==='date'?'date':'text';return `<label class="field"><span>${text(lab)}</span><input ${common} type="${type}" ${schema.min!==undefined?`min="${schema.min}"`:''} ${schema.maxLength?`maxlength="${schema.maxLength}"`:''} ${schema.pattern?`pattern="${text(schema.pattern)}"`:''} placeholder="${text(hint)}"><small class="mini">${req?'Required · ':''}${text(hint||schema.type||'Text value')}${schema.relation?` · enter an existing canonical ${text(schema.relation)} code` :''}</small></label>`}

function samplePayload(d){const out={};for(const f of d?.fields||[]){const sc=d?.fieldSchemas?.[f]||{};if(f==='states')out[f]=[{code:'created',initial:true,terminal:false},{code:'completed',initial:false,terminal:true}];else if(f==='transitions')out[f]=[{from:'created',to:'completed',action:'complete',requiresAuthorization:true}];else if(f==='prerequisites')out[f]=[{code:'authorized',required:true}];else if(f==='evidenceRequirements')out[f]=[{type:'proof',required:true}];else if(f==='recoveryPaths')out[f]=[{from:'failed',action:'retry_or_escalate'}];else if(f==='translations')out[f]={'mission.create.title':'Create mission','mission.create.submit':'Create','common.cancel':'Cancel'};else if(OBJECT_FIELDS.has(f))out[f]={};else if(f==='name'||f==='title')out[f]=`Example ${d.label||'Asset'}`;else if(f==='code')out[f]=`example-${String(d.entryType||'asset').toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;else if(f==='countryCode')out[f]='DE';else if(f==='sectorCode')out[f]='logistics';else if(f==='localeCode'||f==='defaultLanguageCode')out[f]='en';else if(f==='fallbackLocale')out[f]='en';else if(f==='direction')out[f]='ltr';else if(f==='version')out[f]='auto';else if(f==='billingInterval')out[f]='month';else if(sc.type==='boolean')out[f]=Boolean(sc.default);else if(sc.type==='enum')out[f]=sc.options?.[0]||'';else out[f]=''}return out}
function addForm(type){const d=definitions.find(x=>x.entryType===type);if(!d)return '';const contract=buildAssetContract(d,'create');const fields=contract.fields.map(f=>f.name);return `<section class="card section resource-add-editor asset-studio-editor"><div class="section-head"><div><span class="eyebrow">ASSET STUDIO · ${text(d.category||'PLATFORM')}</span><h2>${text(d.label)}</h2><p class="sub">One complete workspace for this asset contract. Fields come from the owning authority; no parallel asset record is created.</p></div><span class="pill ${riskClass(d.risk)}">${text(String(d.risk||'low').toUpperCase())} RISK</span></div><div class="resource-create-contract"><div><span>CANONICAL AUTHORITY</span><b>${text(contract.authority||'Canonical authority')}</b></div><div><span>ASSET FAMILY</span><b>${text(contract.family)}</b></div><div><span>GOVERNED COMMIT</span><b>Validate → Authorize → Commit → Read back</b></div></div><div class="asset-studio-sections"><span>IDENTITY & SCOPE</span><span>TYPE-SPECIFIC CONFIGURATION</span><span>RELATIONSHIPS & GOVERNANCE</span><span>REVIEW & COMMIT</span></div><details class="resource-json-intake"><summary>Import or copy a JSON example</summary><p class="mini">Example only. Import does not bypass schema validation, authorization or canonical commit.</p><div class="actions"><button type="button" class="btn muted" id="resourceCopySample">COPY SAMPLE JSON</button><button type="button" class="btn muted" id="resourceLoadSample">LOAD SAMPLE INTO FIELDS</button></div><textarea id="resourceJsonInput" class="input" rows="8" spellcheck="false" aria-label="Resource JSON intake">${text(JSON.stringify(samplePayload(d),null,2))}</textarea><div class="actions"><button type="button" class="btn muted" id="resourceApplyJson">APPLY JSON TO FIELDS</button><input type="file" id="resourceJsonFile" accept=".json,application/json" class="input" aria-label="Import JSON file"></div><div id="resourceJsonResult" class="mini" role="status"></div></details><form id="resourceAddForm" class="form-grid asset-studio-form" novalidate><div class="resource-form-section full"><span class="eyebrow">COMPLETE THE ASSET CONTRACT</span><p class="mini">All supported fields are visible together. The server remains authoritative for validation, scope, dependencies, lifecycle and permissions.</p></div>${fields.map((field,i)=>`<div class="resource-wizard-field ${i%3===0?'asset-field-wide':''}" data-wiz-field="${i}">${fieldInput(field,d)}</div>`).join('')}<div class="actions full resource-wizard-actions"><button class="btn primary" type="submit" id="resourceWizardSubmit">VALIDATE & CREATE ASSET</button><button class="btn muted" type="button" id="resourceAddCancel">CANCEL</button></div></form><div id="resourceAddResult" role="status" aria-live="polite"></div></section>`}
function assetFamily(d){try{return buildAssetContract(d,'create').family}catch{return ASSET_FAMILIES[0]}}
function bindResourceWizard(type){const form=$('#resourceAddForm');if(!form)return;const d=definitions.find(x=>x.entryType===type);const fields=[...form.querySelectorAll('[data-wiz-field]')];fields.forEach(w=>w.hidden=false);form._showField=el=>{el?.closest('[data-wiz-field]')?.scrollIntoView({behavior:'smooth',block:'center'});el?.focus()};const applyJson=obj=>{if(!obj||typeof obj!=='object'||Array.isArray(obj))throw new Error('JSON must be one object whose keys match this resource schema.');const allowed=new Set(d?.fields||[]),unknown=Object.keys(obj).filter(k=>!allowed.has(k));if(unknown.length)throw new Error(`Unknown field(s) for ${d?.label}: ${unknown.join(', ')}`);for(const [key,value] of Object.entries(obj)){const el=form.querySelector(`[data-field="${CSS.escape(key)}"]`);if(!el)continue;if(el.type==='checkbox')el.checked=Boolean(value);else el.value=OBJECT_FIELDS.has(key)?JSON.stringify(value??{},null,2):String(value??'')}const note=$('#resourceJsonResult');if(note)note.textContent='JSON applied to matching fields. Review all values before validation.'};$('#resourceCopySample').onclick=async()=>{try{await navigator.clipboard.writeText(JSON.stringify(samplePayload(d),null,2));$('#resourceJsonResult').textContent='Sample JSON copied.'}catch{$('#resourceJsonResult').textContent='Clipboard unavailable; select and copy the sample from the editor.'}};$('#resourceLoadSample').onclick=()=>{try{applyJson(samplePayload(d))}catch(e){$('#resourceJsonResult').textContent=e.message}};$('#resourceApplyJson').onclick=()=>{try{applyJson(JSON.parse($('#resourceJsonInput').value||'{}'))}catch(e){$('#resourceJsonResult').textContent=e.message||'Invalid JSON.'}};$('#resourceJsonFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>1024*1024){$('#resourceJsonResult').textContent='File exceeds 1 MiB limit.';e.target.value='';return}try{$('#resourceJsonInput').value=await f.text();JSON.parse($('#resourceJsonInput').value);$('#resourceJsonResult').textContent='JSON file loaded. Click APPLY JSON TO FIELDS after reviewing it.'}catch{$('#resourceJsonResult').textContent='File is not valid JSON.'}};form.addEventListener('submit',e=>{for(const wrap of fields){const input=wrap.querySelector('input,textarea,select');if(input?.required&&!(input.type==='checkbox'?input.checked:String(input.value||'').trim())){e.preventDefault();input.focus();input.reportValidity?.();break}}},true)}
function renderShell(box){box.innerHTML=`<div class="resource-management resource-studio-v2"><div class="eyebrow">CONTROL PLANE · CANONICAL ASSETS</div><div class="resource-hero"><div><h1 class="title">Asset Studio</h1><p class="sub">One unified workspace · one canonical truth · six asset families · governed create and update.</p></div><div class="resource-hero-actions"><button class="btn primary" id="resourceCreateAsset">CREATE ASSET</button><button class="btn muted" id="resourceRefresh">REFRESH</button></div></div><nav class="resource-studio-nav" aria-label="Resource Studio sections"><button type="button" class="active" data-resource-view="assets">ASSETS <span>Browse & manage</span></button><button type="button" data-resource-view="create">CREATE <span>One-screen contract form</span></button><button type="button" data-resource-view="monitor">MONITOR <span>Health & dependencies</span></button></nav><section class="resource-studio-panel" data-resource-panel="assets"><section class="card section"><div class="section-head"><div><span class="eyebrow">CANONICAL INVENTORY</span><h2 id="resourceResultsTitle">Last updated assets</h2><p class="sub">Search, filter, create, and manage canonical assets.</p></div><span id="resourceResultsCount" class="pill neutral">0</span></div><div class="resource-search-form"><input id="resourceSearchInput" class="input" autocomplete="off" placeholder="Search asset name, code, type or identity…"><button type="button" class="btn primary" id="resourceSearchButton">SEARCH</button></div><div class="resource-inventory-controls"><label><span>ASSET TYPE</span><select id="resourceFilterType" class="input"><option value="all">All types</option></select></label><label><span>LIFECYCLE</span><select id="resourceFilterStatus" class="input"><option value="all">All states</option><option value="draft">Draft</option><option value="active">Active</option><option value="published">Published</option><option value="blocked">Blocked</option><option value="retired">Retired</option><option value="unknown">Unknown / other</option></select></label><button type="button" class="btn muted" id="resourceClearFilters">CLEAR</button><span id="resourceFilterSummary" class="mini">Sorted by most recently updated.</span></div><div id="resourceResults" class="resource-results"><div class="empty">Loading canonical assets…</div></div></section><section class="card section resource-workspace-card"><div class="section-head"><div><span class="eyebrow">SELECTED ASSET · SINGLE CONTROL SURFACE</span><h2>Asset workspace</h2><p class="sub">Configuration, lifecycle, dependencies, and governed actions.</p></div><span class="pill neutral">CANONICAL AUTHORITY</span></div><div id="resourceWorkspace" class="resource-workspace-empty"><div class="empty">Select an asset above to open its workflow.</div></div></section></section><section class="resource-studio-panel" data-resource-panel="create" hidden><section class="card section"><div class="section-head"><div><span class="eyebrow">CREATE A REUSABLE ASSET</span><h2>Choose what you want to create</h2><p class="sub">The owning authority defines available fields, required relationships and validation. Existing assets should be reused where possible.</p></div></div><div id="resourceQuickTypes" class="resource-quick-types"></div></section><section id="resourceAddMount"></section></section><section class="resource-studio-panel" data-resource-panel="monitor" hidden><section class="resource-monitor-grid" id="resourceMonitorMetrics"><article class="card"><span>CANONICAL ASSETS</span><b>—</b><small>Waiting for canonical inventory</small></article><article class="card"><span>ACTIVE / PUBLISHED</span><b>—</b><small>Authority-reported lifecycle</small></article><article class="card"><span>DRAFT / BLOCKED</span><b>—</b><small>Requires review where applicable</small></article><article class="card"><span>DEPENDENCY AWARENESS</span><b>ON</b><small>Impact preview before governed changes</small></article></section><section class="card section"><div class="section-head"><div><span class="eyebrow">ASSET MONITORING</span><h2>Recent changes and attention</h2><p class="sub">Signals are derived from returned canonical records; this view does not invent health or certify readiness.</p></div><button class="btn muted" id="resourceMonitorRefresh">REFRESH</button></div><div id="resourceMonitorList" class="resource-results"><div class="empty">Loading asset activity…</div></div></section><section class="card section"><div class="section-head"><div><span class="eyebrow">DEPENDENCY EXPLORER</span><h2>Find an asset to inspect its graph</h2><p class="sub">Choose an asset from recent results or search in Assets. The graph only displays canonical relationships exposed by its owner.</p></div><button class="btn primary" id="resourceMonitorBrowse">BROWSE ASSETS</button></div><div id="resourceMonitorGraphHint" class="notice">Select an asset in Assets, then open Dependencies to inspect related records.</div></section></section></div>`}
function showResourceView(view){const chosen=['assets','create','monitor'].includes(view)?view:'assets';document.querySelectorAll('[data-resource-panel]').forEach(p=>p.hidden=p.dataset.resourcePanel!==chosen);document.querySelectorAll('[data-resource-view]').forEach(b=>b.classList.toggle('active',b.dataset.resourceView===chosen));state.resourceStudioView=chosen;if(chosen==='monitor')renderResourceMonitor();}
function renderResourceMonitor(){const host=$('#resourceMonitorMetrics'),list=$('#resourceMonitorList');if(!host||!list)return;const all=recent||[],count=all.length,active=all.filter(r=>['active','published','ready','committed'].includes(String(r.status||'').toLowerCase())).length,attention=all.filter(r=>['draft','blocked','failed','retired','unknown'].includes(String(r.status||'unknown').toLowerCase())).length;host.innerHTML=`<article class="card"><span>RECENT CANONICAL ASSETS</span><b>${count}</b><small>Current returned inventory window</small></article><article class="card"><span>ACTIVE / PUBLISHED</span><b>${active}</b><small>Reported by owning authorities</small></article><article class="card"><span>DRAFT / ATTENTION</span><b>${attention}</b><small>Drafts and non-active states in this window</small></article><article class="card"><span>IMPACT PREVIEW</span><b>AVAILABLE</b><small>Not a substitute for authorization</small></article>`;list.innerHTML=all.slice(0,12).map((r,i)=>`<button type="button" class="resource-result-row" data-monitor-index="${i}"><span class="resource-result-icon">${text(label(r.type).slice(0,1))}</span><span class="resource-result-main"><b>${text(r.name)}</b><small>${text(r.subtitle||label(r.type))}</small></span><span class="resource-result-meta"><strong>${text(String(r.status||'UNKNOWN').toUpperCase())}</strong><small>${text(r.updatedAt||'')}</small></span></button>`).join('')||'<div class="empty">No canonical resources were returned in the current inventory window.</div>';list.querySelectorAll('[data-monitor-index]').forEach(b=>b.onclick=()=>{showResourceView('assets');selectResource(all[Number(b.dataset.monitorIndex)])})}

function renderQuickTypes(){const host=$("#resourceQuickTypes");if(!host)return;const groups=new Map();for(const d of definitions.slice().sort((a,b)=>String(a.category).localeCompare(String(b.category))||String(a.label).localeCompare(String(b.label)))){const key=String(d.category||"platform");if(!groups.has(key))groups.set(key,[]);groups.get(key).push(d)}host.innerHTML=[...groups.entries()].map(([category,list])=>`<section class="resource-create-group"><div class="resource-create-group-head"><span class="eyebrow">${text(category.replaceAll("_"," ").toUpperCase())}</span><span class="mini">${list.length} asset type${list.length===1?'':'s'}</span></div><div class="resource-create-cards">${list.map(d=>{const relations=(d.fields||[]).filter(f=>d.fieldSchemas?.[f]?.relation).map(f=>`${f} → ${d.fieldSchemas[f].relation}`);return `<article class="resource-create-card"><div class="resource-create-card-top"><span class="resource-result-icon">${text(String(d.label||'A').slice(0,1))}</span><span class="pill ${riskClass(d.risk)}">${text(String(d.risk||'low').toUpperCase())}</span></div><h3>${text(d.label)}</h3><p>${text(d.description||'Reusable governed canonical asset.')}</p><div class="resource-create-card-meta"><span>OWNER</span><b>${text(d.authority||'Canonical authority')}</b><span>FIELDS</span><b>${(d.fields||[]).length}</b><span>RELATIONSHIPS</span><b>${relations.length?text(relations.join(' · ')):'Validated by owning authority'}</b></div><button type="button" class="btn primary" data-create-resource="${text(d.entryType)}">CREATE ${text(String(d.label).toUpperCase())}</button></article>`}).join('')}</div></section>`).join('')||'<div class="empty">No reusable resource definitions are currently exposed by the canonical authority.</div>';host.querySelectorAll('[data-create-resource]').forEach(b=>b.onclick=()=>showAdd(b.dataset.createResource))}

function renderResults(items,title){
 const host=$('#resourceResults');if(!host)return;
 visibleResources=Array.isArray(items)?items:[];
 $('#resourceResultsTitle').textContent=title||'Resources';
 const typeFilter=$('#resourceFilterType');
 if(typeFilter){const types=[...new Set(visibleResources.map(r=>String(r.type||'unknown')))].sort();const selected=inventoryFilters.type;typeFilter.innerHTML='<option value="all">All resource types</option>'+types.map(t=>`<option value="${text(t)}">${text(label(t))}</option>`).join('');typeFilter.value=types.includes(selected)?selected:'all';if(!types.includes(selected))inventoryFilters.type='all';}
 applyInventoryFilters();
}
function applyInventoryFilters(){
 const host=$('#resourceResults');if(!host)return;
 const type=inventoryFilters.type,status=inventoryFilters.status;
 const matches=visibleResources.filter(r=>{const t=String(r.type||'unknown'),s=String(r.status||'unknown').toLowerCase();const statusMatch=status==='all'||(status==='unknown'?!['draft','active','published','blocked','retired'].includes(s):s===status);return(type==='all'||t===type)&&statusMatch;});
 $('#resourceResultsCount').textContent=String(matches.length);
 const summary=$('#resourceFilterSummary');if(summary)summary.textContent=`${matches.length} shown · ${visibleResources.length} returned by canonical search. Filters apply to this result set only.`;
 host.innerHTML=matches.map((r,i)=>`<button type="button" class="resource-result-row" data-result-index="${i}"><span class="resource-result-icon">${text(label(r.type).slice(0,1))}</span><span class="resource-result-main"><b>${text(r.name)}</b><small>${text(r.subtitle||label(r.type))}</small></span><span class="resource-result-meta"><strong>${text(String(r.status||'OBSERVED').toUpperCase())}</strong><small>${text(r.updatedAt||'')}</small></span></button>`).join('')||'<div class="empty">No resources match these filters. Clear filters or run another canonical search.</div>';
 if(inventoryHealth.state==='PARTIAL'){
  const details=inventoryHealth.unavailableAuthorities.map(x=>`${x.authority}: ${x.code}`).join(' · ');
  host.insertAdjacentHTML('afterbegin',`<div class=notice role=alert data-inventory-health><strong>Partial canonical inventory.</strong> Some authorities could not be read; results and counts may be incomplete. ${text(details)} <button type="button" class="btn muted" id="resourceRetryInventory">RETRY INVENTORY</button></div>`);
  $('#resourceRetryInventory')?.addEventListener('click',()=>loadRecent());
 }else if(inventoryHealth.state==='COMPLETE'){
  host.insertAdjacentHTML('afterbegin','<div class="sub" role="status" data-inventory-health>Inventory sources reported complete on the last inventory refresh.</div>');
 }
 host.querySelectorAll('[data-result-index]').forEach(b=>b.onclick=()=>selectResource(matches[Number(b.dataset.resultIndex)]));
}

async function loadRecent(){try{const r=await api('/api/platform/admin/resource-management/recent?limit=100');inventoryHealth={state:r.inventoryState==='PARTIAL'?'PARTIAL':r.inventoryState==='COMPLETE'?'COMPLETE':'UNKNOWN',unavailableAuthorities:Array.isArray(r.unavailableAuthorities)?r.unavailableAuthorities:[]};recent=(Array.isArray(r.resources)?r.resources:[]).map(x=>({...x,type:canonicalType(x.type),id:String(x.id??''),updatedAt:x.updatedAt||x.updated_at||''})).filter(x=>x.type&&x.id).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));renderResults(recent,'Canonical assets')}catch(e){inventoryHealth={state:'UNKNOWN',unavailableAuthorities:[{authority:'inventory',code:'INVENTORY_UNAVAILABLE'}]};recent=[];const host=$('#resourceResults');if(host)host.innerHTML=`<div class="authority-unavailable-state"><h3>${text(e.message||'Canonical asset inventory unavailable')}</h3><p class="sub">The canonical inventory could not be loaded. No alternate record source is substituted, so counts and identities cannot silently diverge.</p><button type="button" class="btn muted" id="resourceRetryInventory">RETRY</button></div>`;$('#resourceRetryInventory')?.addEventListener('click',()=>loadRecent());const count=$('#resourceResultsCount');if(count)count.textContent='—';}}
async function search(q){const id=++currentSearchId;const query=String(q||'').trim();if(query.length<2){renderResults(recent,'Last updated resources');return}$('#resourceResults').innerHTML='<div class="empty">Searching canonical resources…</div>';try{const r=await api(`/api/platform/admin/resource-search?q=${encodeURIComponent(query)}&limit=40`);if(id!==currentSearchId)return;const items=(r.results||[]).map(x=>({type:x.type,id:String(x.id),name:x.name||'Resource',status:x.status||'observed',subtitle:x.subtitle||`${label(x.type)} · ${x.id}`,updatedAt:x.updated_at||x.updatedAt||''}));renderResults(items,`Search results for “${query}”`)}catch(e){if(id===currentSearchId)$('#resourceResults').innerHTML=`<div class="authority-unavailable-state"><h3>${text(e.message||'Resource search unavailable')}</h3><p class="sub">No fallback resource state is shown.</p></div>`}}
