function consumerBoundary(type){if(['role','capability','responsibility'].includes(type))return{title:'Authorization and responsibility reference',description:'This resource can participate in authorization decisions only through canonical authorization and responsibility services.',references:'Roles, responsibilities, secured domain policies',access:'Authorized identities in their tenant/context'};if(['policy','residency','retention','consent'].includes(type))return{title:'Governed platform policy reference',description:'This resource can constrain product and operational behavior where the owning policy authority references it.',references:'Products, country configuration and governed processing paths',access:'Consumers satisfying the applicable policy and tenant scope'};return{title:'Reusable platform resource',description:'This resource is canonical platform data that can be referenced by product composition and other governed platform authorities.',references:'Products, country foundations, configuration and operational projections where supported',access:'Consumers through tenant isolation, authorization and product eligibility'};}
