function graphHtml(g){const root=g.root||{};const nodes=(g.nodes||[]).filter(n=>n.id!==root.id);if(!nodes.length)return '<div class="empty">No connected canonical relationships are currently exposed.</div>';return `<div class="resource-dependency-list"><div class="resource-dependency-root"><b>${text(root.label||root.key)}</b><small>${text(root.type)}</small></div>${nodes.map(n=>`<button class="resource-dependency-node" data-rw-node data-rw-type="${text(n.type)}" data-rw-id="${text(n.key)}" data-rw-label="${text(n.label)}"><span><b>${text(n.label)}</b><small>${text(n.type)} · ${text(n.status||'UNKNOWN')}</small></span><span>›</span></button>`).join('')}</div>`}
